        { ime: "I'm Free Tours", opis: "Pješačke ture po središtu uz plaćanje po vlastitoj procjeni.", link: "https://imfree.tours/" },
        { ime: "Fullers360", opis: "Trajekti i izleti na otoke zaljeva Hauraki.", link: "https://www.fullers.co.nz/" }
